from load import R, claimed, rej, PROD, DEV
import table as T

REPO = '/Users/kevingalligan/devel/framejob/.claude/worktrees/help-docs/'
CAT = REPO + 'build/Build/Products/Debug/Frame Job Debug.app/Contents/Resources/agent-catalog.json'
TOOLS = {x['name']: x for x in json.load(open(CAT))['tools']}
TAX = [s for s in json.load(open(B + 'taxonomy.json'))['sections'] if s['id'] == 'mcp'][0]
PAGES = {p['slug']: p for p in TAX['pages']}

def kebab(s):
    s = re.sub(r'[`\'’"]', '', s.lower())
    return re.sub(r'[^a-z0-9]+', '-', s).strip('-')

# --- guide anchors from evidence
HEAD = {}
def headings(path):
    if path not in HEAD:
        out = []
        try:
            for i, l in enumerate(open(REPO + path), 1):
                m = re.match(r'#{1,6} (.+)', l)
                if m: out.append((i, m.group(1).strip()))
        except OSError:
            pass
        HEAD[path] = out
    return HEAD[path]
def slug(h):
    s = h.lower().replace('`', '')
    s = re.sub(r'[^\w\- ]', '', s)
    return s.replace(' ', '-')
def guide_of(r):
    m = re.search(r'(docs/guide/[\w-]+\.md):(\d+)', r['evidence'])
    if not m: return ''
    hs = [h for h in headings(m.group(1)) if h[0] <= int(m.group(2))]
    return f"{m.group(1)}#{slug(hs[-1][1])}" if hs else m.group(1)
def code_of(r):
    out = []
    for m in re.finditer(r'((?:app|core|mcp-proxy|designs)/[\w/+.\-]+\.(?:swift|rs|md))(?::(\d+))?', r['evidence']):
        if m.group(1).startswith('designs/'): continue
        out.append(m.group(1) + (':' + m.group(2) if m.group(2) else ''))
    return out

# --- argument lines
def arg_line(tool, name):
    sch = TOOLS[tool]['inputSchema']
    v = sch.get('properties', {}).get(name)
    if v is None: return None
    bits = []
    t = v.get('type')
    if t: bits.append(t if isinstance(t, str) else '|'.join(map(str, t)))
    if name in sch.get('required', []): bits.append('required')
    if 'enum' in v: bits.append('one of ' + ', '.join('null' if e is None else str(e) for e in v['enum']))
    if 'minimum' in v or 'maximum' in v: bits.append(f"{v.get('minimum', '')}…{v.get('maximum', '')}")
    if 'minItems' in v: bits.append(f"at least {v['minItems']} item(s)")
    return f"Argument {name} ({'; '.join(bits)}): {v.get('description', '').strip()}"
def all_args(tool):
    props = TOOLS[tool]['inputSchema'].get('properties', {})
    return [arg_line(tool, k) for k in props if k not in ('project', 'scope')]

NOISE = re.compile(r'^(Op tool: also takes scope\.?|Agent argument: .*|Recent: .*|Missing from the page.*|Takes the scope envelope key\.?)$')
def clean(d): return d.strip()

def details_from(raws, summary, include_what=True):
    seen, out = {re.sub(r'\W+', ' ', summary.lower()).strip()}, []
    def add(s):
        k = re.sub(r'\W+', ' ', s.lower()).strip()
        if k and k not in seen:
            seen.add(k); out.append(s)
    for i in raws:
        r = R[i]
        trivial = r['name'].startswith(('Tool ', 'Agent tool: '))
        if include_what and not trivial:
            w = r['what'].strip()
            add(w)
        for d in r['details']:
            d = clean(d)
            if not NOISE.match(d): add(d)
    return out

# --- the record set this section must settle
M = set()
for i, r in R.items():
    if i.startswith(('guide-mcp-', 'code-mcp-catalog-')) or r['area'] == 'mcp': M.add(i)
    if any('mcp' in x for x in rej.get(i, [])): M.add(i)
M |= set(T.EXTRA)

tool_page = {t: pg for pg, ts in T.TOOLPAGE.items() for t in ts.split()}
assert set(tool_page) == set(PROD), set(PROD) ^ set(tool_page)

explicit = collections.defaultdict(list)
for s in T.S:
    for i in s['raw']:
        assert i in R, i
        explicit[i].append(s['id'])

# --- tool features: assign what the explicit table left
tokens = re.compile(r'\b(' + '|'.join(sorted(PROD, key=len, reverse=True)) + r')\b')
tool_raw = collections.defaultdict(list)
leftover = []
for i in sorted(M):
    r = R[i]
    if i in T.ASSIGN:
        for t in T.ASSIGN[i]: tool_raw[t].append(i)
        if i not in explicit or True: continue
    if i in explicit: continue
    ts = []
    for m in r['mcp']:
        ts += tokens.findall(m)
    ts = list(dict.fromkeys(ts))
    if not ts:
        ts = list(dict.fromkeys(tokens.findall(r['name'])))
    if not ts or len(ts) > 4:
        leftover.append(i); continue
    for t in ts: tool_raw[t].append(i)
# records that name a tool in an explicit feature still mark the short tool entry
for i in M:
    r = R[i]
    m = re.match(r'(?:Tool |Agent tool: )(\w+)$', r['name'])
    if m and i not in tool_raw[m.group(1)]: tool_raw[m.group(1)].append(i)

def order(raws):
    rank = lambda i: (0 if i.startswith('guide-mcp') else 1 if i.startswith('code-mcp-catalog') else 2, i)
    return sorted(dict.fromkeys(raws), key=rank)

def ui_of(raws):
    out = []
    for i in raws:
        for u in R[i]['ui']:
            if u not in out: out.append(u)
    return out

MENU = re.compile(r'(?:File|Edit|View|Clip|Mark|Insert|Track|Window|Frame Job|Help) ▸ [^,.;()—]+?(?= \(|,|\.|;| —|$)')
KEY = re.compile(r'[⌃⌥⇧⌘]+(?:[A-Z0-9]|[↓↑←→⌫]|,|\.)')
def tool_ui(tool):
    d = TOOLS[tool]['description'][:260]
    first = re.split(r'(?<=[.!?]) ', d)[0]
    return [m.strip() for m in MENU.findall(first)], KEY.findall(first)

def summary_for(tool, raws):
    for pre in ('guide-mcp-', 'code-mcp-catalog-', 'code-screens-'):
        for i in sorted(raws):
            r = R[i]
            if i.startswith(pre) and tokens.findall(' '.join(r['mcp'])) == [tool]:
                return re.sub(r'^An agent can: ', '', r['what']).strip()
    for i in sorted(raws):
        return R[i]['what']
    return TOOLS[tool]['description'].split('. ')[0] + '.'

features = []
def emit(**k): features.append(k)

def finish(fid, name, page, summary, raws, mcp, details, ui=(), shortcuts=(), requires=(), code=(), guide=''):
    raws = order(raws)
    gr = guide
    if not gr:
        for i in raws:
            gr = guide_of(R[i])
            if gr: break
    if not gr:
        gl = PAGES[page].get('guide', [])
        gr = gl[0] if gl else ''
    cr = list(code)
    for i in raws:
        for x in code_of(R[i]):
            if x not in cr: cr.append(x)
    req = list(requires)
    for i in raws:
        for q in R[i]['requires']:
            if q not in req and q != 'none': req.append(q)
    emit(id=fid, name=name, page=page, anchor=kebab(name), summary=summary, ui=list(ui) or ui_of(raws),
         shortcuts=list(shortcuts), mcp=list(mcp), requires=req, details=details, raw_ids=raws,
         guide_ref=gr, code_refs=cr[:8])

for s in T.S:
    det = details_from(order(s['raw']), s['summary'])
    det += s.get('note', [])
    mcp = s['mcp'] + s.get('mcp2', [])
    for tool, a in s.get('args', []) + s.get('args2', []):
        if a is None: det += all_args(tool)
        else:
            l = arg_line(tool, a)
            if l: det.append(l)
    finish(s['id'], s['name'], s['page'], s['summary'], s['raw'], mcp, det,
           ui=s.get('ui', ()), shortcuts=s.get('shortcuts', ()), requires=s.get('requires', ()), code=s.get('code', ()))

for tool in PROD:
    raws = tool_raw[tool]
    page = tool_page[tool]
    summary = summary_for(tool, raws)
    det = details_from(order(raws), summary)
    det += T.NOTES.get(tool, [])
    if tool in T.DETAIL_PAGE:
        det.append(f"Every option is described on {T.DETAIL_PAGE[tool]}.")
    det += [a for a in all_args(tool)]
    props = TOOLS[tool]['inputSchema'].get('properties', {})
    if 'scope' in props: det.append('Op tool: also takes scope, a nest id.')
    det.append('Catalog description: ' + TOOLS[tool]['description'])
    ui, keys = tool_ui(tool)
    finish('mcp-tool-' + tool.replace('_', '-'), tool, page, summary, raws, [tool], det, ui=ui or ui_of(raws), shortcuts=keys)

# --- unique anchors per page, unique ids
seen = collections.Counter()
for f in features:
    k = (f['page'], f['anchor'])
    seen[k] += 1
    if seen[k] > 1:
        f['anchor'] = kebab(f['id'].replace('mcp-', ''))
ids = [f['id'] for f in features]
dup = [k for k, v in collections.Counter(ids).items() if v > 1]
assert not dup, dup

# --- rejected: agent-flavoured records of other areas left for their sections
AREA = {'export': 'export', 'editing': 'editing', 'framing': 'framing', 'assistant': 'assistant', 'color': 'color',
        'captions': 'captions', 'audio': 'audio', 'graphics': 'graphics', 'recording': 'recording', 'timeline': 'timeline',
        'media': 'projects', 'motion': 'motion', 'hdr': 'hdr', 'transcript': 'cleanup', 'speed': 'speed', 'cleanup': 'cleanup',
        'multicam': 'multicam', 'projects': 'projects', 'canvas': 'canvas', 'mattes': 'timeline', 'settings': 'assistant',
        'transitions': 'motion'}
mine = {i for f in features for i in f['raw_ids']}
pat = re.compile(r'\b(' + '|'.join(PROD) + r')\b')
rejected = []
for i, r in R.items():
    if i in mine: continue
    agentish = (r['mcp'] and not r['ui']) or re.search(r'\b(agent|MCP|tool)\b', r['name'], re.I) or pat.search(r['name'])
    if agentish:
        rejected.append(dict(raw_id=i, reason='belongs to ' + AREA.get(r['area'], r['area'])))

out = dict(section='mcp', features=features, rejected=rejected)
os.makedirs(B + 'features', exist_ok=True)
json.dump(out, open(B + 'features/mcp.json', 'w'), ensure_ascii=False, indent=1)

missing = sorted(M - mine)
print('features', len(features), 'rejected', len(rejected), 'M', len(M), 'unsettled', len(missing), 'leftover', leftover[:20])
for i in missing[:60]:
    print(' ', i, R[i]['name'], R[i]['mcp'])
byp = collections.Counter(f['page'] for f in features)
empty = [p for p in PAGES if p not in byp]
print('empty pages', empty)
for p in PAGES: print(f'  {byp[p]:3d} {p}')
print('bytes', os.path.getsize(B + 'features/mcp.json'))

